    /**
     * Errormessage
     */
    errorMessage?: string | null;
    /**
     * Hard Interrupt Requested
     */
    hard_interrupt_requested: boolean;
    /**
     * Id
     */
    id: string;
    /**
     * Pause Requested
     */
    pause_requested: boolean;
    /**
     * Phase
     */
    phase: 'submitted' | 'autonomous_exploration' | 'human_expansion' | 'paused' | 'recovering' | 'review_ready' | 'review_ready_due_to_cap' | 'interrupted' | 'error';
    /**
     * Question
     */
    question: string;
    /**
     * Read Only
     */
    read_only: boolean;
    /**
     * Rootstepid
     */
